import{_ as o,o as d,c as t,a2 as i}from"./chunks/framework.D0_YsCyK.js";const u=JSON.parse('{"title":"安全审计报告（G 域）","description":"","frontmatter":{},"headers":[],"relativePath":"audit/G-security.md","filePath":"audit/G-security.md","lastUpdated":1792448513000}'),a={name:"audit/G-security.md"};function r(c,e,s,l,n,h){return d(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="安全审计报告-g-域" tabindex="-1">安全审计报告（G 域） <a class="header-anchor" href="#安全审计报告-g-域" aria-label="Permalink to &quot;安全审计报告（G 域）&quot;">​</a></h1><h2 id="概要" tabindex="-1">概要 <a class="header-anchor" href="#概要" aria-label="Permalink to &quot;概要&quot;">​</a></h2><ul><li>审查范围：注入 / 认证会话 / SSRF / 越权 / 敏感信息</li><li>发现问题数：<strong>P0 0 个 / P1 1 个 / P2 2 个 / P3 3 个</strong></li><li>审查方式：代码审查 + 实际运行测试验证（JWT 行为测试、HMAC 测试、路由-鉴权交叉脚本、middleware 测试套件）</li><li>审计员：安全审计子代理，2026-10-20</li></ul><h2 id="p1-严重" tabindex="-1">P1 严重 <a class="header-anchor" href="#p1-严重" aria-label="Permalink to &quot;P1 严重&quot;">​</a></h2><h3 id="g-001-自升级-version-参数校验不足-路径注入" tabindex="-1">G-001 自升级 <code>version</code> 参数校验不足（路径注入） <a class="header-anchor" href="#g-001-自升级-version-参数校验不足-路径注入" aria-label="Permalink to &quot;G-001 自升级 `version` 参数校验不足（路径注入）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/system_upgrade.go:178-188</code>（<code>validateUpgradeVersion</code>），调用点 <code>:671</code>（<code>req.Version</code>）、<code>:510</code>（<code>buildSystemUpgradeDownloadURL</code>）、<code>:712</code>（<code>updateEnvVersion</code>）</li><li><strong>现象</strong>：<code>validateUpgradeVersion</code> 仅拒绝控制字符（<code>&lt;0x20</code>、<code>0x7f</code>），未拒绝 <code>/</code>、<code>.</code>、<code>..</code> 等路径字符。用户提交的 <code>version</code> 直接拼入下载 URL：<div class="language-go vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">base </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">:=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> fmt.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">Sprintf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/releases/download/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">...</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, version, filename)</span></span></code></pre></div>构造 <code>version = &quot;1.0.0/../../x&quot;</code> 可改变 URL 路径结构。</li><li><strong>复现步骤</strong>： <ol><li>以管理员身份 POST <code>/api/v1/system/upgrade</code>，body <code>{&quot;version&quot;: &quot;1.0.0/../../../etc&quot;, &quot;channel&quot;: &quot;stable&quot;}</code></li><li>后端构造的下载 URL 路径被改写（实际请求仍命中 github.com，故只会 404，不会 SSRF 到他站）</li></ol></li><li><strong>期望</strong>：version 应匹配 <code>^[0-9][0-9A-Za-z.\\-]*$</code>（与工作流的版本号校验一致，见 <code>docker-build.yml</code> 的 <code>^[0-9][0-9A-Za-z.-]*$</code>）</li><li><strong>实际</strong>：仅校验控制字符</li><li><strong>影响范围</strong>：需管理员权限方可触发；实际危害限于 URL 路径改写导致下载失败（fail-closed），以及 <code>.env</code> 中 <code>FLUX_VERSION</code> 被写入畸形值（不执行，仅影响 compose 解析）</li><li><strong>修复方向</strong>：<code>validateUpgradeVersion</code> 改为正则 <code>^[0-9A-Za-z.\\-]+$</code>，拒绝 <code>/</code>；或在 <code>buildSystemUpgradeDownloadURL</code> 中对 version 做 <code>url.PathEscape</code></li><li><strong>严重度说明</strong>：P1 而非 P0，因为需管理员权限、SecureFetch 锁定目标 host、无实际 SSRF/RCE。</li></ul><h2 id="p2-一般" tabindex="-1">P2 一般 <a class="header-anchor" href="#p2-一般" aria-label="Permalink to &quot;P2 一般&quot;">​</a></h2><h3 id="g-002-联邦-allowedips-的-xff-信任链-残余" tabindex="-1">G-002 联邦 <code>AllowedIPs</code> 的 XFF 信任链（残余） <a class="header-anchor" href="#g-002-联邦-allowedips-的-xff-信任链-残余" aria-label="Permalink to &quot;G-002 联邦 `AllowedIPs` 的 XFF 信任链（残余）&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/federation.go:1762-1800</code>（<code>federationClientIP</code>）</li><li><strong>现象</strong>：注释明确说明信任模型（仅 RemoteAddr 落在可信代理范围时才解析 XFF，从右按 <code>FLVX_TRUSTED_PROXY_HOPS</code> 取），逻辑正确。但 <code>isPeerIPAllowed</code> 的 allowlist 解析未在本轮实测（需真实联邦对端）。</li><li><strong>影响范围</strong>：联邦 peer 白名单绕过（历史 FGH-007 已修复，本轮代码审查确认逻辑正确，未发现新问题）</li><li><strong>修复方向</strong>：无代码修改；建议补充联邦 IP 白名单的集成测试</li><li><strong>分级说明</strong>：P2（防御纵深建议，非可利用漏洞）</li></ul><h3 id="g-003-订阅-user-参数仅绑定-userid-未绑定其他可变参数" tabindex="-1">G-003 订阅 <code>user=</code> 参数仅绑定 userID，未绑定其他可变参数 <a class="header-anchor" href="#g-003-订阅-user-参数仅绑定-userid-未绑定其他可变参数" aria-label="Permalink to &quot;G-003 订阅 `user=` 参数仅绑定 userID，未绑定其他可变参数&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/handler/user_inbound.go:19-29</code>（<code>subURLSig</code>/<code>verifySubURLSig</code>）、<code>kernel_relay.go:540-548</code></li><li><strong>现象</strong>：HMAC 仅覆盖 <code>flvx-subsig-v1:&lt;userID&gt;</code>。<code>?relay=</code>、<code>?format=</code>、<code>?inbound=</code> 参数不在签名内。攻击者持有合法订阅链接时，可任意改 <code>relay</code> 参数枚举该用户有权限的所有中转订阅（但不能越权到无权限的中转——后端仍会按 <code>user_inbound</code> 表二次过滤）。</li><li><strong>复现步骤</strong>： <ol><li>获取用户 A 的合法订阅链接（含有效 <code>user=2&amp;sig=xxx</code>）</li><li>修改 <code>relay=2</code> 为 <code>relay=3</code>（用户 A 有权限的中转）</li><li>可获取用户 A 在中转 3 下的订阅（仍是用户 A 自己的数据）</li></ol></li><li><strong>期望</strong>：签名绑定全部过滤参数，或文档明确说明</li><li><strong>实际</strong>：仅绑定 userID；越权被后端二次过滤拦截（<code>ListUserInboundAssignments</code>），故无 IDOR，但存在&quot;参数可变性&quot;</li><li><strong>影响范围</strong>：信息泄露仅限用户自己的已授权数据，无跨用户越权（已用代码路径确认：<code>kernel_relay.go:543-585</code> 的二次过滤）</li><li><strong>修复方向</strong>：将 <code>relay</code>/<code>inbound</code> 纳入 HMAC，或保持现状并在注释中说明威胁模型</li><li><strong>分级说明</strong>：P2（设计权衡，非漏洞）</li></ul><h2 id="p3-体验-备注" tabindex="-1">P3 体验/备注 <a class="header-anchor" href="#p3-体验-备注" aria-label="Permalink to &quot;P3 体验/备注&quot;">​</a></h2><h3 id="g-004-cors-与-websocket-checkorigin-true" tabindex="-1">G-004 CORS <code>*</code> 与 WebSocket <code>CheckOrigin: true</code> <a class="header-anchor" href="#g-004-cors-与-websocket-checkorigin-true" aria-label="Permalink to &quot;G-004 CORS `*` 与 WebSocket `CheckOrigin: true`&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/middleware/cors.go:6</code>、<code>go-backend/internal/ws/server.go:162</code></li><li><strong>说明</strong>：已在项目设计基线中明确为&quot;设计权衡&quot;（面板需被任意域名反代访问），非新发现。JWT 认证不依赖 Cookie，故 CORS <code>*</code> 不导致 CSRF 劫持会话。记录备查。</li></ul><h3 id="g-005-jwt-无-iat-未来时间校验" tabindex="-1">G-005 JWT 无 <code>iat</code> 未来时间校验 <a class="header-anchor" href="#g-005-jwt-无-iat-未来时间校验" aria-label="Permalink to &quot;G-005 JWT 无 `iat` 未来时间校验&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/auth/jwt.go:84-108</code>（<code>ParseClaims</code>）</li><li><strong>现象</strong>：仅校验 <code>exp</code>，不校验 <code>iat</code> 是否为未来时间。攻击者无法伪造签名，故无法利用；仅为健壮性备注。</li><li><strong>实测</strong>：有效/篡改/过期/错误密钥/alg=none 混淆/空 token 六种场景全部按预期拒绝（自写 <code>TestAuditGJWTBehavior</code> 通过，已清理）</li></ul><h3 id="g-006-api-v1-config-get-的-allowsoptionalauth" tabindex="-1">G-006 <code>/api/v1/config/get</code> 的 <code>allowsOptionalAuth</code> <a class="header-anchor" href="#g-006-api-v1-config-get-的-allowsoptionalauth" aria-label="Permalink to &quot;G-006 `/api/v1/config/get` 的 `allowsOptionalAuth`&quot;">​</a></h3><ul><li><strong>文件</strong>：<code>go-backend/internal/http/middleware/auth.go:117-119</code></li><li><strong>现象</strong>：<code>/api/v1/config/get</code> 允许无 token 访问，但 handler 内对非公开 key 要求登录（<code>handler.go:531-534</code>），敏感 key 要求管理员（<code>:527-530</code>）。逻辑正确，记录备查。</li></ul><h2 id="已验证通过的安全机制-实测" tabindex="-1">已验证通过的安全机制（实测） <a class="header-anchor" href="#已验证通过的安全机制-实测" aria-label="Permalink to &quot;已验证通过的安全机制（实测）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>#</th><th>机制</th><th>证据</th></tr></thead><tbody><tr><td>1</td><td>SQL 注入</td><td>全部 <code>db.Raw</code> 为静态 SQL 或 <code>?</code> 参数化；<code>Order()</code> 全为静态字符串；无字符串拼接 Where。抽查 <code>repository.go:409/3204/3306/3423/4044/4057</code>、<code>migration_r5b4_v1.go:114</code></td></tr><tr><td>2</td><td>命令注入</td><td><code>system_upgrade.go</code> 的 <code>exec.CommandContext</code> 参数均为固定值或经 <code>validateBackendContainerName</code>（<code>^[A-Za-z0-9_.-]+$</code>）校验；<code>buildHelperRunArgs</code> 的 imageID 来自 docker inspect 输出</td></tr><tr><td>3</td><td>路径穿越</td><td><code>gh_mirror.go</code>：host 白名单 + <code>ghMirrorSegment</code> 正则 + 显式拒绝 <code>.</code>/<code>..</code> + 缓存路径为 URL 哈希；<code>tuning.go</code> 备份路径为硬编码常量</td></tr><tr><td>4</td><td>JWT</td><td>自研 HMAC-SHA256：<code>hmac.Equal</code> 常量时间比较；签名覆盖 header（alg 混淆不可能）；过期校验；7 天有效期；<code>PwdChangeRequired</code> 受限 token 仅放行改密接口。六场景实测通过</td></tr><tr><td>5</td><td>登录限流</td><td>R5-B2 A-001 已修复：XFF 从右按 <code>FLVX_TRUSTED_PROXY_HOPS</code> 解析，仅可信代理场景采信；另有按用户名独立限流（30/10min + 指数退避）</td></tr><tr><td>6</td><td>SSRF</td><td><code>SecureFetch</code>：scheme 白名单、私网默认拒绝、元数据地址硬黑名单（169.254.169.254、fd00:ec2::254，含 IPv4-mapped 展开）、公网强制 https、逐 IP 判定、重定向校验；订阅导入、系统升级下载均经此通道</td></tr><tr><td>7</td><td>订阅 IDOR</td><td><code>verifySubURLSig</code> 为 <code>subtle.ConstantTimeCompare</code>；<code>TestSubURLSigRoundTrip/RejectsForged/DifferentSecrets</code> 通过</td></tr><tr><td>8</td><td>越权</td><td>182 条路由与 middleware <code>requiresAdmin</code>/<code>shouldSkip</code> 交叉验证：<code>/api/v1/forward/*</code> 为按隧道授权的 operator 设计（<code>resolveForwardAccess</code>→<code>ensureForwardAccessByActor</code>），非遗漏；联邦接口走 peer token 鉴权（<code>authPeer</code> + 命令白名单）</td></tr><tr><td>9</td><td>敏感信息</td><td>日志无密钥/token（抽查）；<code>IsSensitiveConfigKey</code> 覆盖 jwt_secret 等 9 项；<code>getConfigByName</code>/<code>getConfigs</code> 过滤；前端 <code>SENSITIVE_CONFIG_KEYS</code> 从 localStorage 清除</td></tr><tr><td>10</td><td>流量上报</td><td><code>/flow/upload</code> 凭节点 secret（AES）鉴权；H-17 负值丢弃（<code>flow_upload_batch.go:43</code>）；seq 幂等防重放</td></tr><tr><td>11</td><td>Passkey</td><td>标准 webauthn 库；origin 严格校验（https 或本地 http）；challenge 2 分钟 TTL</td></tr><tr><td>12</td><td>调优/备份</td><td>备份路径硬编码，无用户输入参与</td></tr></tbody></table><h2 id="未能验证的项" tabindex="-1">未能验证的项 <a class="header-anchor" href="#未能验证的项" aria-label="Permalink to &quot;未能验证的项&quot;">​</a></h2><ul><li>联邦 AllowedIPs 的真实跨机器白名单绕过测试（需两个面板实例）</li><li>大规模并发下的限流桶内存占用（<code>loginRateLimitMaxBuckets=10000</code> 上限存在，逻辑正确）</li><li>PostgreSQL 下的信息 schema 查询（代码路径与 SQLite 一致，参数化）</li></ul>',22)])])}const p=o(a,[["render",r]]);export{u as __pageData,p as default};
